mapper.select:
SELECT h.ssp_slot_id AS ssp_slot_id, h.date AS date, SUM(h.show_pv) AS show_pv, SUM(h.click_pv) AS click_pv, SUM(h.req_count) AS req_pv, SUM(h.discard) AS discard, SUM(h.ret_pv) AS ret_pv, SUM(h.spend) AS spend, SUM(h.income) AS income, SUM(h.discount_click_pv) AS discount_click_pv, SUM(h.discount_show_pv) AS discount_show_pv, SUM(h.dplsucc_pv) AS dplsucc_pv, SUM(h.complete_pv) AS complete_pv, SUM(h.install_pv) AS install_pv, SUM(h.activate_pv) AS activate_pv,
MAX(ssp.name_alise) AS sspName, MAX(app.name) AS appName, MAX(app.os_type) AS osType, MAX(media.media_company_short) AS mediaName
FROM data_ssp_slot_hour AS h LEFT JOIN ssp_slot_info AS ssp ON h.ssp_slot_id = ssp.id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id LEFT JOIN ssp_media AS media ON media.id = ssp.media_id
AND h.date = #{reqVO.date[0]}
AND h.date BETWEEN #{reqVO.date[0]} AND #{reqVO.date[1]}
AND h.media_id = #{reqVO.mediaId}
AND app.os_type = #{reqVO.osType}
AND h.app_id IN
#{id}
AND ssp.name_alise IN
#{name}
AND h.ssp_slot_id IN
#{id}
AND h.dsp_slot_id IN
#{id}
AND h.dsp_slot_code = #{reqVO.dspSlotCode}
GROUP BY h.ssp_slot_id, h.date ORDER BY h.date DESC
